#!/usr/bin/env python3
# Generates src/RecursiveAI.OneEcma/Syntax/Ast.cs from the compact node table below.
# The output is committed; rerun after editing the table:  python3 tools/gen-ast.py
import os
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'src', 'RecursiveAI.OneEcma', 'Syntax', 'Ast.cs')

# name : base | doc | fields: (type, name, doc)
N = []
def n(name, base, doc, *fields): N.append((name, base, doc, fields))

E='Expression'; S='Statement'
