# Node (statement) is a Node too; Statement/Expression are abstract bases.
out = []
w = out.append
w('// <auto-generated>Generated by tools/gen-ast.py. Edit the table there and regenerate.</auto-generated>')
w('#nullable enable\nnamespace RecursiveAI.OneEcma.Syntax;\n')
w('/// <summary>Every kind of syntax node; the <see cref="Node.Kind"/> of each class.</summary>')
w('public enum NodeKind\n{')
for name, *_ in N:
    w(f'    /// <summary><see cref="{name}"/>.</summary>\n    {name},')
w('}\n')
for name, base, doc, fields in N:
    w(f'/// <summary>{doc}</summary>')
    params = ', '.join(['int start', 'int end'] + [f'{t} @{f[0].lower()+f[1:]}' for t, f, d in fields])
    w(f'public sealed class {name} : {base}\n{{')
    w(f'    internal {name}({params})\n        : base(start, end)\n    {{')
    for t, f, d in fields:
        w(f'        {f} = @{f[0].lower()+f[1:]};')
    w('    }\n')
    w(f'    /// <inheritdoc/>\n    public override NodeKind Kind => NodeKind.{name};')
    for t, f, d in fields:
        w(f'\n    /// <summary>{d}</summary>\n    public {t} {f} {{ get; {"internal set; " if f == "IsAnnexBHoisted" else ""}}}')
    w('}\n')
open(root, 'w').write('\n'.join(out))
